import * as tf from '@tensorflow/tfjs';
import '@tensorflow/tfjs-backend-webgpu';

await tf.setBackend('webgpu');
await tf.ready();

const ativacoes = tf.ones([16, 64]); // Batch de 16 exemplos, 64 neurônios
const bias = tf.ones([64]);          // Vetor de bias com 64 elementos
const resultado = tf.add(ativacoes, bias);

const before = tf.memory().numTensors;

const output = tf.tidy(() => {
  const a = tf.tensor1d([1, 2, 3]);
  const b = tf.tensor1d([4, 5, 6]);
  const sum = a.add(b);
  const squared = sum.square();
  return squared;
});

const after = tf.memory().numTensors;
console.log(after - before);

const computeMseLoss = (yPred: tf.Tensor2D, yTrue: tf.Tensor2D): tf.Scalar => {
  return yPred.sub(yTrue).square().mean() as tf.Scalar;
};
